INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (471, 1, 'mdb 객체', '`bridge mdb` 객체는 무엇을 담을까요?', '멀티캐스트예요.', NULL, NULL, '[]', 'choice', '["링크의 알려진 유니캐스트 MAC 주소 목록", "VLAN ID 필터 항목 목록 전체", "알려진 IP·L2 멀티캐스트 그룹 주소", "포트별 STP 상태 값 목록 전체"]', 2, '문서는 mdb 객체가 링크의 알려진 IP 또는 L2 멀티캐스트 그룹 주소를 담고, 항목을 표시·추가·교체·삭제하는 명령이 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 2, 'mdb 채움', '`bridge mdb show` 로 보는 멀티캐스트 그룹 표는 어떻게 채워질까요?', '스누핑이에요.', NULL, NULL, '[]', 'choice', '["오직 수동 add 로만 채워진다", "IGMP·MLD 스누핑이 자동으로 채운다", "라우팅 데몬이 읽어 와서만 채워진다", "STP 가 선출 과정에서 채운다"]', 1, '문서는 표가 브리지 드라이버의 IGMP·MLD 스누핑으로 자동 채워지며 bridge mdb add·del 로 수동 변경도 가능하다고 설명합니다.', NULL, NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 3, 'port', '`bridge mdb add dev br0 port eth1 grp ...` 에서 **port** 는 무엇일까요?', '멤버가 있는 쪽이에요.', NULL, NULL, '[]', 'choice', '["그룹 멤버가 있는 것으로 알려진 링크가 연결된 포트", "멀티캐스트를 송신하는 호스트의 UDP 포트 번호", "그룹 주소가 속한 브리지 장치", "쿼리를 보낼 목적지 포트 번호"]', 0, '문서는 port 가 이 멀티캐스트 그룹의 멤버가 있다고 알려진 링크의 포트이고, grp 는 그 포트에 연결된 링크에 멤버가 있는 그룹 주소라고 설명합니다.', NULL, NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 4, 'permanent·temp', 'mdb 항목의 `permanent` 와 `temp` 에 대한 설명으로 맞는 것은 무엇일까요?', 'L2 는 달라요.', NULL, NULL, '[]', 'choice', '["permanent 가 기본이며 temp 는 L2 그룹에서 필수다", "둘 다 선택이고 L2 도 예외가 없다", "temp 는 IPv4 전용, permanent 는 IPv6 전용이다", "temp 가 기본이며 permanent 는 L2 그룹에서 필수다"]', 3, '문서는 permanent 가 IPv4·IPv6 에서는 선택, L2 에서는 필수이고 temp(임시)가 기본이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 5, 'src', 'mdb 항목의 `src SOURCE` 는 언제 조회에 쓰일까요?', '버전이 따로 있어요.', NULL, NULL, '[]', 'choice', '["IGMPv1 이 켜져 있을 때만 포함된다", "브리지에 STP 가 켜져 있을 때만 포함된다", "IGMPv3·MLDv2 가 켜져 있으면 포함된다", "VXLAN 장치에서만 쓸 수 있다"]', 2, '문서는 src 가 이 그룹의 송신자 IP 이며 IGMPv3(IPv4) 또는 MLDv2(IPv6)가 활성일 때 멀티캐스트 전달 조회에 포함된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 6, 'filter_mode', '`filter_mode` 와 `source_list` 에 대한 설명으로 맞는 것은 무엇일까요?', '(*, G) 항목이에요.', NULL, NULL, '[]', 'choice', '["(S, G) 항목에만 설정할 수 있다", "(*, G) 에만 가능, 목록 쓰면 모드 필수", "아무 항목에나 쓸 수 있고 항상 선택이다", "VXLAN 장치에서만 설정할 수 있다"]', 1, '문서는 filter_mode(include·exclude)와 source_list 가 (*, G) 항목에만 설정할 수 있고, source_list 를 쓰면 그 송신자 패킷의 전달 여부를 정하는 filter_mode 가 필수 인자가 된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 7, 'proto', 'mdb 항목에 `proto` 를 주지 않으면 라우팅 프로토콜 식별자는 무엇일까요?', '/etc/iproute2/rt_protos 가 있어요.', NULL, NULL, '[]', 'choice', '["static 으로 간주한다", "kernel 로 간주한다", "boot 로 간주한다", "0 번 프로토콜로 간주한다"]', 0, '문서는 proto 가 숫자나 /etc/iproute2/rt_protos 의 문자열이며, 주지 않으면 static 이라고 가정한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 8, 'catchall', 'mdb 의 `0.0.0.0` 과 `::` 항목은 무엇일까요?', '특별 항목이에요.', NULL, NULL, '[]', 'choice', '["모든 멀티캐스트를 차단하는 항목이다", "브리지 자신을 가리키는 로컬 항목이다", "쿼리어 선출에 쓰는 항목이다", "등록 안 된 멀티캐스트용 플러딩 항목"]', 3, '문서는 0.0.0.0 과 :: MDB 항목이 각각 등록되지 않은 IPv4·IPv6 멀티캐스트를 플러딩하는 catchall 이며, 이 항목을 두면 00:00:00:00:00:00 FDB catchall 은 브로드캐스트·알 수 없는 유니캐스트·링크 로컬 멀티캐스트만 플러딩한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 9, 'show 옵션', '`bridge -details mdb show` 는 추가로 무엇을 보여 줄까요?', '라우터 포트예요.', NULL, NULL, '[]', 'choice', '["항목별 마지막 사용 시각만 보인다", "항목이 만들어진 프로토콜 이름만 보인다", "라우터가 연결된 것으로 아는 포트", "포트별 패킷 통계 전체가 보인다"]', 2, '문서는 -details 가 출력을 자세히 하여 라우터가 연결된 것으로 알려진 포트를 보여 주고, -statistics 는 mdb·라우터 포트 항목의 타이머 값을 보여 준다고 설명합니다.', NULL, NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 10, 'mdb 삭제', '기존 mdb 항목을 **삭제하는** 하위 명령입니다. 빈칸을 채우세요.', '인자는 add 와 같아요.', NULL, NULL, '[]', 'fill', '["del", "add", "replace", "get"]', NULL, '문서는 delete(del) 가 기존 mdb 항목을 지우며 인자가 add 와 같다고 설명합니다. replace 는 일치 항목이 없으면 새로 만듭니다.', '[0]', 'bridge mdb {0} dev br0 port eth1 grp 239.1.1.1', NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 11, 'temp', '기본값인 **임시** 항목을 뜻하는 키워드입니다. 빈칸을 채우세요.', '영구의 반대예요.', NULL, NULL, '[]', 'fill', '["temp", "permanent", "static", "dynamic"]', NULL, '문서는 temp 가 임시 항목이고 기본값이라고 설명합니다. permanent 는 영구 항목입니다.', '[0]', 'bridge mdb add dev br0 port eth1 grp 239.1.1.1 {0}', NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]'),
  (471, 12, 'mdb 다루기', 'mdb 항목을 확인하고 수동으로 다루는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '보고 → 넣고 → 조회 → 지워요.', NULL, NULL, '[]', 'order', '["`bridge mdb show dev br0` 로 스누핑이 채운 그룹 표를 본다", "`bridge mdb add dev br0 port eth1 grp 239.1.1.1` 로 항목을 수동 추가한다", "`bridge mdb get dev br0 grp 239.1.1.1` 로 항목을 조회한다", "`bridge mdb del dev br0 port eth1 grp 239.1.1.1` 로 항목을 지운다"]', NULL, '문서의 mdb show·add·get·delete 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "bridge(8) man page", "url": "https://man7.org/linux/man-pages/man8/bridge.8.html"}]');
